<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useStudyStore } from '../stores/useStudyStore'
import WeekUploadModal from '../components/cycle/WeekUploadModal.vue'
import WeekDetailDrawer from '../components/cycle/WeekDetailDrawer.vue'
import SettingsModal from '../components/settings/SettingsModal.vue'
import NavbarHeader from '../components/common/NavbarHeader.vue'
const store = useStudyStore(); const upload = ref<typeof store.weeks[0] | null>(null); const detail = ref<typeof store.weeks[0] | null>(null); const settingsOpen = ref(false); onMounted(store.hydrate)
const status = (state: string) => state === 'completada' ? 'Completada' : state === 'procesada' ? 'En progreso' : 'Pendiente'
</script>
<template><div><NavbarHeader @settings="settingsOpen = true" /><main class="mx-auto max-w-7xl px-5 py-10"><div class="mb-8 max-w-2xl"><p class="font-bold uppercase tracking-widest text-accent">Tu ciclo de aprendizaje</p><h1 class="mt-2 text-4xl font-black">Matemática discreta, sin distracciones.</h1><p class="mt-3 text-lg text-slate-500">Organiza 4 módulos × 4 semanas y convierte cada concepto en práctica.</p></div><div class="grid gap-8 md:grid-cols-2"><section v-for="module in 4" :key="module"><h2 class="mb-3 text-xl font-bold">Módulo {{ module }}</h2><div class="grid grid-cols-2 gap-3"><button v-for="week in store.weeks.filter(w => w.modulo === module)" :key="week.semana" class="card text-left hover:-translate-y-0.5 hover:border-accent" @click="week.estado === 'pendiente' ? upload = week : detail = week"><span class="text-sm text-slate-500">Semana {{ week.semana }}</span><strong class="mt-2 block">{{ status(week.estado) }}</strong><span class="mt-3 block h-1.5 rounded bg-slate-100 dark:bg-slate-800"><span class="block h-full rounded bg-accent" :style="{ width: week.estado === 'completada' ? '100%' : week.estado === 'procesada' ? '45%' : '0%' }" /></span></button></div></section></div></main><WeekUploadModal v-if="upload" :week="upload" @close="upload = null" @processed="store.updateWeek($event); upload = null; detail = $event" /><WeekDetailDrawer v-if="detail" :week="detail" @close="detail = null" @exam="$router.push(`/exam/${detail.modulo}/${detail.semana}`)" /><SettingsModal v-if="settingsOpen" :settings="store.settings" @close="settingsOpen = false" @save="store.updateSettings($event); settingsOpen = false" /></div></template>
